it('registers through its service provider and merges its config', function () {
    TestApp::boot();
    expect(config('connectors.slack.mode'))->toBe('auto');
    expect(config('connectors.slack.credentials'))->toBeArray();
});

it('fakes message_post and records it for assertSent', function () {
    TestApp::boot();
    Slack::fake();
    $config = [
        'channel' => 'example-channel',
        'text' => 'example-text',
        'blocks' => '[{"type":"section","text":{"type":"mrkdwn","text":"Ticket *42*"}}]',
    ];
    $result = Slack::call('message_post', $config);

    expect($result->mode->value)->toBe('fake');
    Slack::assertSent('message_post', fn (array $sent): bool => $sent == $config);
    Slack::assertNotSent('no_such_operation');
    Slack::assertSentCount(1);
});

it('refuses a forged block_actions delivery before the app sees it', function () {
    $app = TestApp::boot();
    $app['router']->slackBlockActions('/hooks/slack');
    $response = TestApp::dispatch($app, Request::create('/hooks/slack', 'POST', server: ['CONTENT_TYPE' => 'application/json'], content: '{"forged":true}'));

    expect($response->getStatusCode())->toBe(401);
});
